  /** What the agent should do; becomes the GitHub issue body. Must not be only whitespace. */
  instruction: string;
  /** Agent to route to. Omit to use the instance default. */
  agentAlias?: string;
  /** Model of the agent. Omit to use the agent default. */
  model?: string;
  /** Repository to-dos this submission resolves. */
  todoIds?: string[];
  autoMerge?: boolean;
  runUltrafix?: boolean;
  /** Requires `runUltrafix: true`. */
